import 'package:family_veda/models/member.dart';
import 'package:family_veda/providers/members_provider.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

/// The profile to open on by default: the user's own, else the first listed.
Member? preferredMember(List<Member> members) =>
    members.where((member) => member.isSelf).firstOrNull ??
    members.firstOrNull;

final activeMemberProvider = StateProvider<String?>(
  (ref) => preferredMember(ref.watch(membersProvider).valueOrNull ?? const [])?.id,
);
